261	template <typename FPTYPE>
262	void deepmd::tabulate_fusion_se_a_grad_grad_cpu(FPTYPE* dz_dy,
263	                                                const FPTYPE* table,
264	                                                const FPTYPE* table_info,
265	                                                const FPTYPE* em_x,
266	                                                const FPTYPE* em,
267	                                                const FPTYPE* two_embed,
268	                                                const FPTYPE* dz_dy_dem_x,
269	                                                const FPTYPE* dz_dy_dem,
270	                                                const FPTYPE* dz_dy_dtwo,
271	                                                const int nloc,
272	                                                const int nnei,
273	                                                const int last_layer_size,
274	                                                const bool is_sorted) {
275	  bool enable_se_atten = two_embed != nullptr;
276	  memset(dz_dy, 0, sizeof(FPTYPE) * nloc * 4 * last_layer_size);
277	  const FPTYPE lower = table_info[0];
278	  const FPTYPE upper = table_info[1];
279	  const FPTYPE _max = table_info[2];
280	  const FPTYPE stride0 = table_info[3];
281	  const FPTYPE stride1 = table_info[4];
282	// for every atom, execute a small manual gemm ~
283	// FPTYPE * res = new FPTYPE[4 * last_layer_size];
284	#pragma omp parallel for
285	  for (int ii = 0; ii < nloc; ii++) {
286	    FPTYPE ll[4];
287	    FPTYPE hh[4];
288	    FPTYPE ago = em_x[ii * nnei + nnei - 1];
289	    bool unloop = false;
290	    for (int jj = 0; jj < nnei; jj++) {
291	      ll[0] = em[ii * nnei * 4 + jj * 4 + 0];
292	      ll[1] = em[ii * nnei * 4 + jj * 4 + 1];
293	      ll[2] = em[ii * nnei * 4 + jj * 4 + 2];
294	      ll[3] = em[ii * nnei * 4 + jj * 4 + 3];
295	      hh[0] = dz_dy_dem[ii * nnei * 4 + jj * 4 + 0];
296	      hh[1] = dz_dy_dem[ii * nnei * 4 + jj * 4 + 1];
297	      hh[2] = dz_dy_dem[ii * nnei * 4 + jj * 4 + 2];
298	      hh[3] = dz_dy_dem[ii * nnei * 4 + jj * 4 + 3];
299	      FPTYPE xx = em_x[ii * nnei + jj];
300	      FPTYPE dz_xx = dz_dy_dem_x[ii * nnei + jj];
301	      if (ago == xx && ll[1] == 0. && ll[2] == 0. && ll[3] == 0. && is_sorted) {
302	        unloop = true;
303	      }
304	      int table_idx = 0;
305	      locate_xx(lower, upper, _max, stride0, stride1, xx, table_idx);
306	      for (int kk = 0; kk < last_layer_size; kk++) {
307	        FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * kk + 0];
308	        FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * kk + 1];
309	        FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * kk + 2];
310	        FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * kk + 3];
311	        FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * kk + 4];
312	        FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * kk + 5];
313	        FPTYPE var =
314	            a0 + (a1 + (a2 + (a3 + (a4 + a5 * xx) * xx) * xx) * xx) * xx;
315	        FPTYPE var_grad =
316	            a1 +
317	            ((FPTYPE)2. * a2 +
318	             ((FPTYPE)3. * a3 + ((FPTYPE)4. * a4 + (FPTYPE)5. * a5 * xx) * xx) *
319	                 xx) *
320	                xx;
321	        FPTYPE two_grad = 0.;
322	        if (enable_se_atten) {
323	          FPTYPE t = two_embed[ii * nnei * last_layer_size +
324	                               jj * last_layer_size + kk];
325	          // dz_dy_dtwo * var * ll
326	          // var above should be used instead of var + var * t below
327	          two_grad = dz_dy_dtwo[ii * nnei * last_layer_size +
328	                                jj * last_layer_size + kk] *
329	                     var;
330	          var += var * t;
331	          var_grad += var_grad * t;
332	        }
333	
334	        /*
335	         * `dz_dy` represents the derivative of the variable `out` in the
336	         * function `deepmd::tabulate_fusion_se_a_cpu`.
337	         *
338	         * The expression `var * hh[0] + dz_xx * var_grad * ll[0]` utilizes the
339	         * product rule of derivatives: `(f * g)' = f' * g + f * g'`.
340	         *
341	         * This expression can be alternatively expressed as:
342	         * `hh[0] * var + ll[0] * (dz_xx * var_grad)`.
343	         * Note that `hh[0]` is one element of `em`, and `ll[0]` is one element
344	         * of `dz_dy_dem` which is `em'`.
345	         *
346	         * Therefore, we can rewrite this expression as: `em' * var + em *
347	         * var'`, where `em'` is the derivative of `em` and `var'` is the
348	         * derivative of `var`. Additionally, `var'` can be further represented
349	         * as: `var_grad * dz_xx`.
350	         *
351	         * If `enable_se_atten` is true, `var` will be `var * t + var`, and
352	         * `var'` will be `(var_grad * t + var_grad) * dz_xx`.
353	         */
354	        if (unloop) {
355	          dz_dy[ii * last_layer_size * 4 + 0 * last_layer_size + kk] +=
356	              (nnei - jj) *
357	              (var * hh[0] + (dz_xx * var_grad + two_grad) * ll[0]);
358	          dz_dy[ii * last_layer_size * 4 + 1 * last_layer_size + kk] +=
359	              (nnei - jj) *
360	              (var * hh[1] + (dz_xx * var_grad + two_grad) * ll[1]);
361	          dz_dy[ii * last_layer_size * 4 + 2 * last_layer_size + kk] +=
362	              (nnei - jj) *
363	              (var * hh[2] + (dz_xx * var_grad + two_grad) * ll[2]);
364	          dz_dy[ii * last_layer_size * 4 + 3 * last_layer_size + kk] +=
365	              (nnei - jj) *
366	              (var * hh[3] + (dz_xx * var_grad + two_grad) * ll[3]);
367	        } else {
368	          dz_dy[ii * last_layer_size * 4 + 0 * last_layer_size + kk] +=
369	              var * hh[0] + (dz_xx * var_grad + two_grad) * ll[0];
370	          dz_dy[ii * last_layer_size * 4 + 1 * last_layer_size + kk] +=
371	              var * hh[1] + (dz_xx * var_grad + two_grad) * ll[1];
372	          dz_dy[ii * last_layer_size * 4 + 2 * last_layer_size + kk] +=
373	              var * hh[2] + (dz_xx * var_grad + two_grad) * ll[2];
374	          dz_dy[ii * last_layer_size * 4 + 3 * last_layer_size + kk] +=
375	              var * hh[3] + (dz_xx * var_grad + two_grad) * ll[3];
376	        }
377	      }
378	      if (unloop) {
379	        break;
380	      }
381	    }
382	  }
383	}
