489	void deepmd::tabulate_fusion_se_t_grad_grad_cpu(FPTYPE* dz_dy,
490	                                                const FPTYPE* table,
491	                                                const FPTYPE* table_info,
492	                                                const FPTYPE* em_x,
493	                                                const FPTYPE* em,
494	                                                const FPTYPE* dz_dy_dem_x,
495	                                                const FPTYPE* dz_dy_dem,
496	                                                const int nloc,
497	                                                const int nnei_i,
498	                                                const int nnei_j,
499	                                                const int last_layer_size) {
500	  memset(dz_dy, 0, sizeof(FPTYPE) * nloc * last_layer_size);
501	  const FPTYPE lower = table_info[0];
502	  const FPTYPE upper = table_info[1];
503	  const FPTYPE _max = table_info[2];
504	  const FPTYPE stride0 = table_info[3];
505	  const FPTYPE stride1 = table_info[4];
506	// for every atom, execute a small manual gemm ~
507	// FPTYPE * res = new FPTYPE[4 * last_layer_size];
508	#pragma omp parallel for
509	  for (int ii = 0; ii < nloc; ii++) {
510	    for (int jj = 0; jj < nnei_i; jj++) {
511	      for (int kk = 0; kk < nnei_j; kk++) {
512	        FPTYPE xx = em_x[ii * nnei_i * nnei_j + jj * nnei_j + kk];
513	        FPTYPE tmp = xx;
514	        FPTYPE dz_em = dz_dy_dem[ii * nnei_i * nnei_j + jj * nnei_j + kk];
515	        FPTYPE dz_xx = dz_dy_dem_x[ii * nnei_i * nnei_j + jj * nnei_j + kk];
516	
517	        int table_idx = 0;
518	        locate_xx_se_t(lower, upper, -_max, _max, stride0, stride1, xx,
519	                       table_idx);
520	        for (int mm = 0; mm < last_layer_size; mm++) {
521	          FPTYPE a0 = table[table_idx * last_layer_size * 6 + 6 * mm + 0];
522	          FPTYPE a1 = table[table_idx * last_layer_size * 6 + 6 * mm + 1];
523	          FPTYPE a2 = table[table_idx * last_layer_size * 6 + 6 * mm + 2];
524	          FPTYPE a3 = table[table_idx * last_layer_size * 6 + 6 * mm + 3];
525	          FPTYPE a4 = table[table_idx * last_layer_size * 6 + 6 * mm + 4];
526	          FPTYPE a5 = table[table_idx * last_layer_size * 6 + 6 * mm + 5];
527	          FPTYPE var =
528	              a0 + (a1 + (a2 + (a3 + (a4 + a5 * xx) * xx) * xx) * xx) * xx;
529	          FPTYPE var_grad =
530	              a1 + ((FPTYPE)2. * a2 +
531	                    ((FPTYPE)3. * a3 +
532	                     ((FPTYPE)4. * a4 + (FPTYPE)5. * a5 * xx) * xx) *
533	                        xx) *
534	                       xx;
535	
536	          dz_dy[ii * last_layer_size + mm] +=
537	              var * dz_em + dz_xx * var_grad * tmp;
538	        }
539	      }
540	    }
541	  }
