input.content:
// Comprehensive consistency harness for the compressed-DP tabulation kernels.
// Independent of reproduce.py: builds Hermite-consistent tables (C2 across
// interval boundaries) from smooth test functions and checks, for every
// supported descriptor family:
//   forward          vs an independent spec-based reference evaluation
//   grad             vs central finite differences of the forward contraction
//   grad_grad        vs finite differences of the grad contraction wrt `dy`
// Sampled points include interior points, exact table nodes, the lower/upper/
// max boundaries, and points outside the stored range, across several valid
// table configurations.

#include "tabulate.h"

#include <cmath>
#include <cstdio>
#include <random>
#include <string>
#include <vector>

namespace {

std::mt19937_64 rng(20240817);

double uni(double a, double b) {
  return a + (b - a) * std::uniform_real_distribution<double>(0.0, 1.0)(rng);
}

struct Config {
  std::string name;
  double lower, upper, maxv, s0, s1;
};

// ---- independent reference table response (written from the method spec) ----
// Piecewise fifth-order table: [lower, upper) with stride0, [upper, max) with
// stride1. Outside the stored range the first/last interval polynomial is
// extended, so value and derivative stay one coherent response.
void ref_eval(const Config& c, const std::vector<double>& table, int L, int mm,
              double x, double& val, double& der) {
  const int n0 = (int)((c.upper - c.lower) / c.s0);
  const int n1 = (int)((c.maxv - c.upper) / c.s1);
  int idx;
  double base;
  if (x < c.lower) {
    idx = 0;
    base = c.lower;
  } else if (x < c.upper) {
    idx = (int)((x - c.lower) / c.s0);
    base = c.lower + idx * c.s0;
  } else if (x < c.maxv) {
    idx = n0 + (int)((x - c.upper) / c.s1);
    base = c.upper + (idx - n0) * c.s1;
  } else {
    idx = n0 + n1 - 1;
    base = c.upper + (n1 - 1) * c.s1;
  }
  const double xl = x - base;
  const double* a = &table[(idx * L + mm) * 6];
  val = a[0] + (a[1] + (a[2] + (a[3] + (a[4] + a[5] * xl) * xl) * xl) * xl) * xl;
  der = a[1] + (2.0 * a[2] + (3.0 * a[3] + (4.0 * a[4] + 5.0 * a[5] * xl) * xl) * xl) * xl;
}

// se_t layout: central dense region [lower, upper) stride0 inside
// [min=-max, max) with stride1 on both flanks; same edge extension.
void ref_eval_se_t(const Config& c, const std::vector<double>& table, int L,
                   int mm, double x, double& val, double& der) {
  const double minv = -c.maxv;
  const int f1 = (int)((c.lower - minv) / c.s1);
  const int f2 = f1 + (int)((c.upper - c.lower) / c.s0);
  const int n3 = (int)((c.maxv - c.upper) / c.s1);
  int idx;
  double base;
  if (x < minv) {
    idx = 0;
    base = minv;
  } else if (x < c.lower) {
    idx = (int)((x - minv) / c.s1);
    base = minv + idx * c.s1;
  } else if (x < c.upper) {
    idx = f1 + (int)((x - c.lower) / c.s0);
    base = c.lower + (idx - f1) * c.s0;
  } else if (x < c.maxv) {
    idx = f2 + (int)((x - c.upper) / c.s1);
    base = c.upper + (idx - f2) * c.s1;
  } else {
    idx = f2 + n3 - 1;
    base = c.upper + (n3 - 1) * c.s1;
  }
  const double xl = x - base;
  const double* a = &table[(idx * L + mm) * 6];
  val = a[0] + (a[1] + (a[2] + (a[3] + (a[4] + a[5] * xl) * xl) * xl) * xl) * xl;
  der = a[1] + (2.0 * a[2] + (3.0 * a[3] + (4.0 * a[4] + 5.0 * a[5] * xl) * xl) * xl) * xl;
}

// ---- Hermite-consistency helpers ----
struct SmoothFn {
  double A, B, C, D, E, F;
  double f(double x) const { return A * std::sin(B * x + C) + D * std::cos(E * x + F); }
  double fp(double x) const { return A * B * std::cos(B * x + C) - D * E * std::sin(E * x + F); }
  double fpp(double x) const {
    return -A * B * B * std::sin(B * x + C) - D * E * E * std::cos(E * x + F);
  }
};

void solve3(double m[3][4], double out[3]) {
  for (int col = 0; col < 3; ++col) {
    int piv = col;
    for (int r = col + 1; r < 3; ++r)
      if (std::fabs(m[r][col]) > std::fabs(m[piv][col])) piv = r;
    for (int cc = col; cc < 4; ++cc) std::swap(m[piv][cc], m[col][cc]);
    const double d = m[col][col];
    for (int r = col + 1; r < 3; ++r) {
      const double f = m[r][col] / d;
      for (int cc = col; cc < 4; ++cc) m[r][cc] -= f * m[col][cc];
    }
  }
  for (int r = 2; r >= 0; --r) {
    double s = m[r][3];
    for (int cc = r + 1; cc < 3; ++cc) s -= m[r][cc] * out[cc];
    out[r] = s / m[r][r];
  }
}

void hermite_coeffs(const SmoothFn& fn, double h, double* c) {
  c[0] = fn.f(0.0);
  c[1] = fn.fp(0.0);
  c[2] = fn.fpp(0.0) / 2.0;
  const double r0 = fn.f(h) - (c[0] + c[1] * h + c[2] * h * h);
  const double r1 = fn.fp(h) - (c[1] + 2.0 * c[2] * h);
  const double r2 = fn.fpp(h) - 2.0 * c[2];
  double m[3][4] = {{h * h * h, h * h * h * h, h * h * h * h * h, r0},
                    {3 * h * h, 4 * h * h * h, 5 * h * h * h * h, r1},
                    {6 * h, 12 * h * h, 20 * h * h * h, r2}};
  double o[3];
  solve3(m, o);
  c[3] = o[0];
  c[4] = o[1];
  c[5] = o[2];
}

// standard two-stride table (se_a / se_r layout)
std::vector<double> build_table(const Config& c, int L) {
  const int n0 = (int)((c.upper - c.lower) / c.s0);
  const int n1 = (int)((c.maxv - c.upper) / c.s1);
  std::vector<double> table((n0 + n1) * L * 6);
  for (int mm = 0; mm < L; ++mm) {
    SmoothFn fn{uni(-1.5, 1.5), uni(0.5, 2.5), uni(-3, 3),
                uni(-1.5, 1.5), uni(0.5, 2.5), uni(-3, 3)};
    for (int i = 0; i < n0; ++i) {
      double c6[6];
      hermite_coeffs(SmoothFn{fn.A, fn.B, fn.C + fn.B * (c.lower + i * c.s0),
                              fn.D, fn.E, fn.F + fn.E * (c.lower + i * c.s0)},
                     c.s0, c6);
      for (int p = 0; p < 6; ++p) table[(i * L + mm) * 6 + p] = c6[p];
    }
    for (int j = 0; j < n1; ++j) {
      const double x0 = c.upper + j * c.s1;
      double c6[6];
      hermite_coeffs(SmoothFn{fn.A, fn.B, fn.C + fn.B * x0, fn.D, fn.E,
                              fn.F + fn.E * x0},
                     c.s1, c6);
      for (int p = 0; p < 6; ++p) table[((n0 + j) * L + mm) * 6 + p] = c6[p];
    }
  }
  return table;
}

// se_t table: [-max, lower) stride1, [lower, upper) stride0, [upper, max) stride1
std::vector<double> build_table_se_t(const Config& c, int L) {
  const double minv = -c.maxv;
  const int f1 = (int)((c.lower - minv) / c.s1);
  const int f0 = (int)((c.upper - c.lower) / c.s0);
  const int n3 = (int)((c.maxv - c.upper) / c.s1);
  std::vector<double> table((f1 + f0 + n3) * L * 6);
  for (int mm = 0; mm < L; ++mm) {
    SmoothFn fn{uni(-1.5, 1.5), uni(0.5, 2.5), uni(-3, 3),
                uni(-1.5, 1.5), uni(0.5, 2.5), uni(-3, 3)};
    int seg = 0;
    for (int i = 0; i < f1; ++i, ++seg) {
      const double x0 = minv + i * c.s1;
      double c6[6];
      hermite_coeffs(SmoothFn{fn.A, fn.B, fn.C + fn.B * x0, fn.D, fn.E,
                              fn.F + fn.E * x0},
                     c.s1, c6);
      for (int p = 0; p < 6; ++p) table[(seg * L + mm) * 6 + p] = c6[p];
    }
    for (int i = 0; i < f0; ++i, ++seg) {
      const double x0 = c.lower + i * c.s0;
      double c6[6];
      hermite_coeffs(SmoothFn{fn.A, fn.B, fn.C + fn.B * x0, fn.D, fn.E,
                              fn.F + fn.E * x0},
                     c.s0, c6);
      for (int p = 0; p < 6; ++p) table[(seg * L + mm) * 6 + p] = c6[p];
    }
    for (int i = 0; i < n3; ++i, ++seg) {
      const double x0 = c.upper + i * c.s1;
      double c6[6];
      hermite_coeffs(SmoothFn{fn.A, fn.B, fn.C + fn.B * x0, fn.D, fn.E,
                              fn.F + fn.E * x0},
                     c.s1, c6);
      for (int p = 0; p < 6; ++p) table[(seg * L + mm) * 6 + p] = c6[p];
    }
  }
  return table;
}

std::vector<double> table_info(const Config& c) {
  return {c.lower, c.upper, c.maxv, c.s0, c.s1, -1.0};
}

double central(const std::vector<double>& v, int i, double h,
               const std::function<double(const std::vector<double>&)>& fn) {
  std::vector<double> up = v, dn = v;
  up[i] += h;
  dn[i] -= h;
  return (fn(up) - fn(dn)) / (2 * h);
}

struct Stats {
  double worst = 0.0;
  std::string what;
  int checks = 0;
  void see(const std::string& name, double err) {
    ++checks;
    if (err > worst) {
      worst = err;
      what = name;
    }
  }
};

Stats g_stats;

void run_family(const Config& c) {
  const int L = 4;
  const int nloc = 2;
  const int nnei = 3;
  const std::vector<double> tab = build_table(c, L);
  const std::vector<double> ti = table_info(c);
  const double span = c.maxv - c.lower;

  // raw inputs spanning below-lower .. above-max
  std::vector<double> em_x(nloc * nnei), em(nloc * nnei * 4),
      two(nloc * nnei * L), dy(nloc * nnei * L * 4), w(nloc * nnei * L);
  for (auto& v : em_x) v = uni(c.lower - 0.25 * span, c.maxv + 0.25 * span);
  for (auto& v : em) v = uni(-1.0, 1.0);
  for (auto& v : two) v = uni(-0.5, 0.5);
  for (auto& v : dy) v = uni(-1.0, 1.0);
  for (auto& v : w) v = uni(-1.0, 1.0);

  // ---------------- se_r ----------------
  {
    std::vector<double> out(nloc * nnei * L);
    deepmd::tabulate_fusion_se_r_cpu<double>(out.data(), tab.data(), ti.data(),
                                             em_x.data(), nloc, nnei, L);
    for (int ii = 0; ii < nloc; ++ii)
      for (int jj = 0; jj < nnei; ++jj)
        for (int mm = 0; mm < L; ++mm) {
          double val, der;
          ref_eval(c, tab, L, mm, em_x[ii * nnei + jj], val, der);
          g_stats.see("se_r fwd", std::fabs(out[(ii * nnei + jj) * L + mm] - val));
        }
    // grad: dy_dem[jj] = d(sum(out*w))/d em_x[jj]
    auto energy = [&](const std::vector<double>& x) {
      std::vector<double> o(x.size() * L);
      deepmd::tabulate_fusion_se_r_cpu<double>(o.data(), tab.data(), ti.data(),
                                               x.data(), nloc, nnei, L);
      double e = 0;
      for (size_t i = 0; i < o.size(); ++i) e += o[i] * w[i];
      return e;
    };
    std::vector<double> dy_em(nloc * nnei);
    deepmd::tabulate_fusion_se_r_grad_cpu<double>(dy_em.data(), tab.data(),
                                                  ti.data(), em_x.data(),
                                                  w.data(), nloc, nnei, L);
    for (int i = 0; i < nloc * nnei; ++i)
      g_stats.see("se_r grad",
                  std::fabs(dy_em[i] - central(em_x, i, 1e-6, energy)));
    // grad_grad: dz_dy = d(sum(dz_dy_dem * dy_em))/d dy
    std::vector<double> zdem(nloc * nnei);
    for (auto& v : zdem) v = uni(-1.0, 1.0);
    std::vector<double> dz_dy(nloc * nnei * L);
    deepmd::tabulate_fusion_se_r_grad_grad_cpu<double>(
        dz_dy.data(), tab.data(), ti.data(), em_x.data(), zdem.data(), nloc,
        nnei, L);
    auto zfun = [&](const std::vector<double>& d) {
      std::vector<double> de(nloc * nnei);
      deepmd::tabulate_fusion_se_r_grad_cpu<double>(de.data(), tab.data(),
                                                    ti.data(), em_x.data(),
                                                    d.data(), nloc, nnei, L);
      double z = 0;
      for (int i = 0; i < nloc * nnei; ++i) z += de[i] * zdem[i];
      return z;
    };
    for (size_t i = 0; i < w.size(); ++i)
      g_stats.see("se_r grad_grad",
                  std::fabs(dz_dy[i] - central(w, (int)i, 1e-6, zfun)));
  }

  // ---------------- se_a (unsorted) ----------------
  {
    for (int use_two = 0; use_two < 2; ++use_two) {
      const double* two_p = use_two ? two.data() : nullptr;
      std::vector<double> out(nloc * nnei * 4 * L);
      deepmd::tabulate_fusion_se_a_cpu<double>(out.data(), tab.data(), ti.data(),
                                               em_x.data(), em.data(), two_p,
                                               nloc, nnei, L, false);
      for (int ii = 0; ii < nloc; ++ii)
        for (int cc = 0; cc < 4; ++cc)
          for (int mm = 0; mm < L; ++mm) {
            double expect = 0;
            for (int jj = 0; jj < nnei; ++jj) {
              double val, der;
              ref_eval(c, tab, L, mm, em_x[ii * nnei + jj], val, der);
              if (use_two) val += val * two[(ii * nnei + jj) * L + mm];
              expect += val * em[(ii * nnei + jj) * 4 + cc];
            }
            g_stats.see(use_two ? "se_atten fwd" : "se_a fwd",
                        std::fabs(out[(ii * 4 + cc) * L + mm] - expect));
          }
      auto energy = [&](const std::vector<double>& ex,
                        const std::vector<double>& e,
                        const std::vector<double>& t) {
        std::vector<double> o(nloc * 4 * L);
        deepmd::tabulate_fusion_se_a_cpu<double>(o.data(), tab.data(),
                                                 ti.data(), ex.data(),
                                                 e.data(),
                                                 use_two ? t.data() : nullptr,
                                                 nloc, nnei, L, false);
        double en = 0;
        for (size_t i = 0; i < o.size(); ++i) en += o[i] * dy[i];
        return en;
      };
      std::vector<double> dyx(nloc * nnei), dem(nloc * nnei * 4),
          dtwo(nloc * nnei * L, 0.0);
      deepmd::tabulate_fusion_se_a_grad_cpu<double>(
          dyx.data(), dem.data(), dtwo.data(), tab.data(), ti.data(),
          em_x.data(), em.data(), two_p, dy.data(), nloc, nnei, L, false);
      for (int i = 0; i < nloc * nnei; ++i)
        g_stats.see(use_two ? "se_atten dy_dem_x" : "se_a dy_dem_x",
                    std::fabs(dyx[i] - central(em_x, i, 1e-6,
                                               [&](const std::vector<double>& x) {
                                                 return energy(x, em, two);
                                               })));
      for (int i = 0; i < nloc * nnei * 4; ++i)
        g_stats.see(use_two ? "se_atten dy_dem" : "se_a dy_dem",
                    std::fabs(dem[i] - central(em, i, 1e-6,
                                               [&](const std::vector<double>& e) {
                                                 return energy(em_x, e, two);
                                               })));
      if (use_two) {
        for (int i = 0; i < nloc * nnei * L; ++i)
          g_stats.see("se_atten dy_dtwo",
                      std::fabs(dtwo[i] - central(two, i, 1e-6,
                                                  [&](const std::vector<double>& t) {
                                                    return energy(em_x, em, t);
                                                  })));
      }
      // grad_grad wrt dy
      std::vector<double> zdx(nloc * nnei), zdem(nloc * nnei * 4),
          zdt(nloc * nnei * L);
      for (auto& v : zdx) v = uni(-1, 1);
      for (auto& v : zdem) v = uni(-1, 1);
      for (auto& v : zdt) v = uni(-1, 1);
      std::vector<double> dzdy(nloc * 4 * L);
      deepmd::tabulate_fusion_se_a_grad_grad_cpu<double>(
          dzdy.data(), tab.data(), ti.data(), em_x.data(), em.data(), two_p,
          zdx.data(), zdem.data(), zdt.data(), nloc, nnei, L, false);
      auto zfun = [&](const std::vector<double>& d) {
        std::vector<double> dx2(nloc * nnei), dm2(nloc * nnei * 4),
            dt2(nloc * nnei * L, 0.0);
        deepmd::tabulate_fusion_se_a_grad_cpu<double>(
            dx2.data(), dm2.data(), dt2.data(), tab.data(), ti.data(),
            em_x.data(), em.data(), two_p, d.data(), nloc, nnei, L, false);
        double z = 0;
        for (int i = 0; i < nloc * nnei; ++i) z += dx2[i] * zdx[i];
        for (int i = 0; i < nloc * nnei * 4; ++i) z += dm2[i] * zdem[i];
        if (use_two)
          for (int i = 0; i < nloc * nnei * L; ++i) z += dt2[i] * zdt[i];
        return z;
      };
      for (size_t i = 0; i < dy.size(); ++i)
        g_stats.see(use_two ? "se_atten grad_grad" : "se_a grad_grad",
                    std::fabs(dzdy[i] - central(dy, (int)i, 1e-6, zfun)));
    }
  }

  // ---------------- se_a sorted/unloop agreement ----------------
  {
    const int nn = 5;  // 3 real + 2 padding
    for (int ii2 = 0; ii2 < 1; ++ii2) {
      std::vector<double> ex = {0.9, 0.62, 0.4, 0.0, 0.0};
      std::vector<double> e4(nn * 4, 0.0), dy4(4 * L * 1);
      for (int j = 0; j < 3; ++j)
        for (int cc = 0; cc < 4; ++cc) e4[j * 4 + cc] = uni(-1, 1);
      for (auto& v : dy4) v = uni(-1, 1);
      std::vector<double> o_sorted(4 * L), o_unsorted(4 * L);
      deepmd::tabulate_fusion_se_a_cpu<double>(o_sorted.data(), tab.data(),
                                               ti.data(), ex.data(), e4.data(),
                                               nullptr, 1, nn, L, true);
      deepmd::tabulate_fusion_se_a_cpu<double>(o_unsorted.data(), tab.data(),
                                               ti.data(), ex.data(),
                                               e4.data(), nullptr, 1, nn, L,
                                               false);
      double expect = 0;
      for (int cc = 0; cc < 4; ++cc)
        for (int mm = 0; mm < L; ++mm) {
          double ref = 0;
          for (int j = 0; j < nn; ++j) {
            double val, der;
            ref_eval(c, tab, L, mm, ex[j], val, der);
            ref += val * e4[j * 4 + cc];
          }
          g_stats.see("se_a sorted fwd",
                      std::fabs(o_sorted[cc * L + mm] - o_unsorted[cc * L + mm]));
          g_stats.see("se_a sorted fwd ref", std::fabs(o_sorted[cc * L + mm] - ref));
          expect += ref;
        }
      (void)expect;
      std::vector<double> dxs(nn), dms(nn * 4), dxu(nn), dmu(nn * 4), dtd(1, 0.0);
      deepmd::tabulate_fusion_se_a_grad_cpu<double>(
          dxs.data(), dms.data(), dtd.data(), tab.data(), ti.data(), ex.data(),
          e4.data(), nullptr, dy4.data(), 1, nn, L, true);
      deepmd::tabulate_fusion_se_a_grad_cpu<double>(
          dxu.data(), dmu.data(), dtd.data(), tab.data(), ti.data(), ex.data(),
          e4.data(), nullptr, dy4.data(), 1, nn, L, false);
      for (int j = 0; j < nn; ++j)
        g_stats.see("se_a sorted dy_dem_x", std::fabs(dxs[j] - dxu[j]));
      // dy_dem layout differs on padding rows; compare contraction with e4
      double cs = 0, cu = 0;
      for (int j = 0; j < nn * 4; ++j) {
        cs += dms[j] * e4[j];
        cu += dmu[j] * e4[j];
      }
      g_stats.see("se_a sorted dy_dem contraction", std::fabs(cs - cu));
    }
  }

  // ---------------- se_t ----------------
  {
    const int ni = 2, nj = 3;
    const std::vector<double> tabt = build_table_se_t(c, L);
    std::vector<double> ex(nloc * ni * nj), e2(nloc * ni * nj), d(nloc * L);
    const double minv = -c.maxv;
    for (auto& v : ex) v = uni(minv - 0.2 * (c.maxv - minv), c.maxv + 0.2 * (c.maxv - minv));
    for (auto& v : e2) v = uni(-1, 1);
    for (auto& v : d) v = uni(-1, 1);
    std::vector<double> out(nloc * L);
    deepmd::tabulate_fusion_se_t_cpu<double>(out.data(), tabt.data(), ti.data(),
                                             ex.data(), e2.data(), nloc, ni,
                                             nj, L);
    for (int ii = 0; ii < nloc; ++ii)
      for (int mm = 0; mm < L; ++mm) {
        double expect = 0;
        for (int jj = 0; jj < ni; ++jj)
          for (int kk = 0; kk < nj; ++kk) {
            double val, der;
            ref_eval_se_t(c, tabt, L, mm, ex[(ii * ni + jj) * nj + kk], val, der);
            expect += val * e2[(ii * ni + jj) * nj + kk];
          }
        g_stats.see("se_t fwd", std::fabs(out[ii * L + mm] - expect));
      }
    auto energy = [&](const std::vector<double>& a, const std::vector<double>& b) {
      std::vector<double> o(nloc * L);
      deepmd::tabulate_fusion_se_t_cpu<double>(o.data(), tabt.data(), ti.data(),
                                               a.data(), b.data(), nloc, ni,
                                               nj, L);
      double e = 0;
      for (int i = 0; i < nloc * L; ++i) e += o[i] * d[i];
      return e;
    };
    std::vector<double> dyx(nloc * ni * nj), dem2(nloc * ni * nj);
    deepmd::tabulate_fusion_se_t_grad_cpu<double>(dyx.data(), dem2.data(),
                                                  tabt.data(), ti.data(),
                                                  ex.data(), e2.data(),
                                                  d.data(), nloc, ni, nj, L);
    for (size_t i = 0; i < ex.size(); ++i)
      g_stats.see("se_t dy_dem_x",
                  std::fabs(dyx[i] - central(ex, (int)i, 1e-6,
                                             [&](const std::vector<double>& a) {
                                               return energy(a, e2);
                                             })));
    for (size_t i = 0; i < e2.size(); ++i)
      g_stats.see("se_t dy_dem",
                  std::fabs(dem2[i] - central(e2, (int)i, 1e-6,
                                              [&](const std::vector<double>& b) {
                                                return energy(ex, b);
                                              })));
    // grad_grad
    std::vector<double> zdx(nloc * ni * nj), zdem(nloc * ni * nj),
        dzdy(nloc * L);
    for (auto& v : zdx) v = uni(-1, 1);
    for (auto& v : zdem) v = uni(-1, 1);
    deepmd::tabulate_fusion_se_t_grad_grad_cpu<double>(
        dzdy.data(), tabt.data(), ti.data(), ex.data(), e2.data(), zdx.data(),
        zdem.data(), nloc, ni, nj, L);
    auto zfun = [&](const std::vector<double>& d2) {
      std::vector<double> dx2(nloc * ni * nj), dm2(nloc * ni * nj);
      deepmd::tabulate_fusion_se_t_grad_cpu<double>(
          dx2.data(), dm2.data(), tabt.data(), ti.data(), ex.data(), e2.data(),
          d2.data(), nloc, ni, nj, L);
      double z = 0;
      for (size_t i = 0; i < zdx.size(); ++i) z += dx2[i] * zdx[i] + dm2[i] * zdem[i];
      return z;
    };
    for (size_t i = 0; i < d.size(); ++i)
      g_stats.see("se_t grad_grad",
                  std::fabs(dzdy[i] - central(d, (int)i, 1e-6, zfun)));
  }

  // ---------------- se_t_tebd ----------------
  {
    const int ni = 2, nj = 3;
    const std::vector<double> tabt = build_table_se_t(c, L);
    std::vector<double> ex(nloc * ni * nj), e2(nloc * ni * nj),
        d(nloc * ni * nj * L);
    for (auto& v : ex) v = uni(-c.maxv - 1.0, c.maxv + 1.0);
    for (auto& v : e2) v = uni(-1, 1);
    for (auto& v : d) v = uni(-1, 1);
    std::vector<double> out(nloc * ni * nj * L);
    deepmd::tabulate_fusion_se_t_tebd_cpu<double>(out.data(), tabt.data(),
                                                  ti.data(), ex.data(),
                                                  e2.data(), nloc, ni, nj, L);
    for (size_t i = 0; i < ex.size(); ++i)
      for (int mm = 0; mm < L; ++mm) {
        double val, der;
        ref_eval_se_t(c, tabt, L, mm, ex[i], val, der);
        g_stats.see("tebd fwd", std::fabs(out[i * L + mm] - val));
      }
    auto energy = [&](const std::vector<double>& a) {
      std::vector<double> o(nloc * ni * nj * L);
      deepmd::tabulate_fusion_se_t_tebd_cpu<double>(o.data(), tabt.data(),
                                                    ti.data(), a.data(),
                                                    e2.data(), nloc, ni, nj,
                                                    L);
      double e = 0;
      for (size_t i = 0; i < o.size(); ++i) e += o[i] * d[i];
      return e;
    };
    std::vector<double> dyx(nloc * ni * nj);
    deepmd::tabulate_fusion_se_t_tebd_grad_cpu<double>(
        dyx.data(), tabt.data(), ti.data(), ex.data(), e2.data(), d.data(),
        nloc, ni, nj, L);
    for (size_t i = 0; i < ex.size(); ++i)
      g_stats.see("tebd dy_dem_x",
                  std::fabs(dyx[i] - central(ex, (int)i, 1e-6, energy)));
    std::vector<double> zdx(nloc * ni * nj), dzdy(nloc * ni * nj * L);
    for (auto& v : zdx) v = uni(-1, 1);
    deepmd::tabulate_fusion_se_t_tebd_grad_grad_cpu<double>(
        dzdy.data(), tabt.data(), ti.data(), ex.data(), e2.data(), zdx.data(),
        nloc, ni, nj, L);
    auto zfun = [&](const std::vector<double>& d2) {
      std::vector<double> dx2(nloc * ni * nj);
      deepmd::tabulate_fusion_se_t_tebd_grad_cpu<double>(
          dx2.data(), tabt.data(), ti.data(), ex.data(), e2.data(), d2.data(),
          nloc, ni, nj, L);
      double z = 0;
      for (size_t i = 0; i < zdx.size(); ++i) z += dx2[i] * zdx[i];
      return z;
    };
    for (size_t i = 0; i < d.size(); ++i)
      g_stats.see("tebd grad_grad",
                  std::fabs(dzdy[i] - central(d, (int)i, 1e-6, zfun)));
  }
}

// boundary / exact-node point sweep for se_r (dense scan over the whole range
// plus outside it), comparing kernel sensitivity with the central FD of the
// kernel's own value contraction and with the analytic reference derivative.
void run_point_sweep(const Config& c) {
  const int L = 3;
  const std::vector<double> tab = build_table(c, L);
  const std::vector<double> ti = table_info(c);
  std::vector<double> wt(L);
  for (auto& v : wt) v = uni(-1, 1);
  auto value = [&](double x) {
    double out[8];
    deepmd::tabulate_fusion_se_r_cpu<double>(out, tab.data(), ti.data(), &x, 1,
                                             1, L);
    double e = 0;
    for (int m = 0; m < L; ++m) e += out[m] * wt[m];
    return e;
  };
  std::vector<double> pts;
  const int n0 = (int)((c.upper - c.lower) / c.s0);
  const int n1 = (int)((c.maxv - c.upper) / c.s1);
  pts.push_back(c.lower - 0.73 * c.s0);
  pts.push_back(c.lower - 0.11 * c.s0);
  pts.push_back(c.lower);
  for (int i = 0; i <= n0; ++i) {
    pts.push_back(c.lower + i * c.s0);            // exact node
    pts.push_back(c.lower + (i + 0.37) * c.s0);   // interior
  }
  for (int j = 0; j <= n1; ++j) {
    pts.push_back(c.upper + j * c.s1);
    pts.push_back(c.upper + (j + 0.53) * c.s1);
  }
  pts.push_back(c.upper);
  pts.push_back(c.maxv);
  pts.push_back(c.maxv + 0.29 * c.s1);
  pts.push_back(c.maxv + 1.13 * c.s1);
  for (double x : pts) {
    double fd = (value(x + 1e-6) - value(x - 1e-6)) / 2e-6;
    double dy0;
    deepmd::tabulate_fusion_se_r_grad_cpu<double>(&dy0, tab.data(), ti.data(),
                                                  &x, wt.data(), 1, 1, L);
    g_stats.see("se_r sweep fd", std::fabs(dy0 - fd));
    double refder = 0;
    for (int m = 0; m < L; ++m) {
      double val, der;
      ref_eval(c, tab, L, m, x, val, der);
      refder += der * wt[m];
    }
    g_stats.see("se_r sweep ref", std::fabs(dy0 - refder));
  }
}

}  // namespace

int main() {
  std::vector<Config> configs = {
      {"cfgA_public_like", -1.0, 1.0, 2.8, 0.5, 0.6},
      {"cfgB_dense", 0.0, 1.2, 2.4, 0.3, 0.4},
      {"cfgC_fine", 0.05, 1.25, 1.85, 0.02, 0.10},
  };
  for (const auto& c : configs) {
    run_family(c);
    run_point_sweep(c);
    std::printf("[%-16s] cumulative worst = %.3e (%s), checks so far = %d\n",
                c.name.c_str(), g_stats.worst, g_stats.what.c_str(),
                g_stats.checks);
  }
  std::printf("TOTAL checks=%d  worst_abs_err=%.4e  at [%s]\n", g_stats.checks,
              g_stats.worst, g_stats.what.c_str());
  if (g_stats.worst > 5e-6) {
    std::printf("FAIL\n");
    return 1;
  }
  std::printf("PASS\n");
  return 0;
}

